package com.ebdf.controller;
import com.ebdf.dao.PortalDAO;import com.ebdf.dao.BloodRequestDetailsDAO;import com.google.gson.Gson;import javax.servlet.annotation.WebServlet;import javax.servlet.http.*;import java.io.*;import java.util.Map;
@WebServlet("/api/blood-requests/responses") public class RequestResponsesServlet extends HttpServlet{
 private final PortalDAO dao=new PortalDAO();private final BloodRequestDetailsDAO details=new BloodRequestDetailsDAO();private final Gson gson=new Gson();
 protected void doGet(HttpServletRequest q,HttpServletResponse p)throws IOException{p.setContentType("application/json");p.setCharacterEncoding("UTF-8");HttpSession s=q.getSession(false);if(s==null||s.getAttribute("userId")==null){p.setStatus(401);p.getWriter().write("{\"message\":\"Please login first\"}");return;}try{int id=Integer.parseInt(q.getParameter("requestId"));Map<String,Object> req=details.getRequestById(id);if(req==null){p.setStatus(404);return;}String role=String.valueOf(s.getAttribute("userRole"));int uid=((Number)s.getAttribute("userId")).intValue();if(!"ADMIN".equals(role)&&!("REQUESTER".equals(role)&&((Number)req.get("requesterUserId")).intValue()==uid)){p.setStatus(403);p.getWriter().write("{\"message\":\"Only the request owner or admin can view donor identities\"}");return;}p.getWriter().write(gson.toJson(dao.requestResponses(id)));}catch(NumberFormatException e){p.setStatus(400);p.getWriter().write("{\"message\":\"Invalid request ID\"}");}catch(Exception e){getServletContext().log("Request responses failed",e);p.setStatus(500);p.getWriter().write("{\"message\":\"Unable to load responses\"}");}}
}
